1	-- 实验盲法分配表结构；运行于 H2 MySQL 兼容模式，数据仅在 JVM 生命周期内保留。
2	
3	CREATE TABLE IF NOT EXISTS experiment (
4	    id          VARCHAR(64)  NOT NULL,
5	    block_count INT          NOT NULL,
6	    status      VARCHAR(16)  NOT NULL,
7	    created_at  BIGINT       NOT NULL,
8	    CONSTRAINT pk_experiment PRIMARY KEY (id),
9	    CONSTRAINT ck_experiment_block_count CHECK (block_count BETWEEN 2 AND 8),
10	    CONSTRAINT ck_experiment_status CHECK (status IN ('OPEN', 'CLOSED'))
11	);
12	COMMENT ON TABLE  experiment IS '实验表，experimentId 全局唯一，创建后区组数量与席位内容不可修改';
13	COMMENT ON COLUMN experiment.id IS '实验编号，业务唯一，创建时由请求给定';
14	COMMENT ON COLUMN experiment.block_count IS '区组数量，取值2~8，创建时固定，每组固定4个席位';
15	COMMENT ON COLUMN experiment.status IS '实验状态：OPEN=开放登记；CLOSED=已关闭，关闭后拒绝新增分配';
