52	COMMENT ON COLUMN allocation.id IS '分配自增主键';
53	COMMENT ON COLUMN allocation.experiment_id IS '所属实验编号';
54	COMMENT ON COLUMN allocation.participant_id IS '合成参与者编号，非真实医疗数据';
55	COMMENT ON COLUMN allocation.block_no IS '分配到的区组号，普通查询可返回';
56	COMMENT ON COLUMN allocation.seat_no IS '分配到的席位号，可直接解码处理代码，禁止通过普通接口暴露';
57	COMMENT ON COLUMN allocation.blind_code IS '随机生成的无含义盲码，全局唯一，与区组/席位无对应规律';
58	COMMENT ON COLUMN allocation.status IS '分配状态：ASSIGNED=在组；WITHDRAWN=已退组（席位仍保留）';
59	COMMENT ON COLUMN allocation.assigned_actor IS '执行登记的操作者编号（X-Actor-Id）';
60	COMMENT ON COLUMN allocation.assigned_at IS '分配时间，Unix 毫秒，UTC';
61	COMMENT ON COLUMN allocation.withdrawn_at IS '退组时间，Unix 毫秒，UTC；NULL 表示未退组';
62	
63	CREATE TABLE IF NOT EXISTS unblind_request (
64	    id                      VARCHAR(64)  NOT NULL,
65	    experiment_id           VARCHAR(64)  NOT NULL,
66	    participant_id          VARCHAR(64)  NOT NULL,
67	    allocation_id           BIGINT       NOT NULL,
68	    reason                  VARCHAR(500) NOT NULL,
69	    applicant_actor         VARCHAR(64)  NOT NULL,
70	    reviewer_actor          VARCHAR(64),
71	    status                  VARCHAR(16)  NOT NULL,
72	    treatment               VARCHAR(1),
73	    created_at              BIGINT       NOT NULL,
74	    reviewed_at             BIGINT,
75	    pending_allocation_id   BIGINT,
76	    CONSTRAINT pk_unblind_request PRIMARY KEY (id),
77	    CONSTRAINT uq_unblind_pending UNIQUE (pending_allocation_id),
78	    CONSTRAINT ck_unblind_status CHECK (status IN ('PENDING', 'APPROVED')),
79	    CONSTRAINT ck_unblind_treatment CHECK (treatment IS NULL OR treatment IN ('A', 'B'))
80	);
81	COMMENT ON TABLE  unblind_request IS '揭盲申请表；同一分配至多一个待审申请，须由另一名 REVIEWER 批准后申请人方可查看结果';
82	COMMENT ON COLUMN unblind_request.id IS '揭盲申请编号，全局唯一';
83	COMMENT ON COLUMN unblind_request.experiment_id IS '所属实验编号';
84	COMMENT ON COLUMN unblind_request.participant_id IS '被申请揭盲的合成参与者编号';
85	COMMENT ON COLUMN unblind_request.allocation_id IS '对应分配主键';
86	COMMENT ON COLUMN unblind_request.reason IS '揭盲原因，必填，非空';
87	COMMENT ON COLUMN unblind_request.applicant_actor IS '申请人操作者编号，须为 COORDINATOR，且只有其本人能查询揭盲结果';
88	COMMENT ON COLUMN unblind_request.reviewer_actor IS '批准的 REVIEWER 操作者编号，必须不同于申请人；未批准时为 NULL';
89	COMMENT ON COLUMN unblind_request.status IS '申请状态：PENDING=待审；APPROVED=已批准';
90	COMMENT ON COLUMN unblind_request.treatment IS '揭盲结果处理代码 A/B，批准时写入；NULL=尚未批准';
91	COMMENT ON COLUMN unblind_request.created_at IS '申请时间，Unix 毫秒，UTC';
92	COMMENT ON COLUMN unblind_request.reviewed_at IS '批准时间，Unix 毫秒，UTC；NULL 表示未批准';
93	COMMENT ON COLUMN unblind_request.pending_allocation_id IS '待审去重列：待审时等于 allocation_id，终态置 NULL；唯一索引保证同一分配至多一个待审申请';
94	
95	CREATE TABLE IF NOT EXISTS idempotent_request (
96	    request_id      VARCHAR(64)  NOT NULL,
97	    actor_id        VARCHAR(64)  NOT NULL,
98	    role            VARCHAR(16)  NOT NULL,
99	    operation       VARCHAR(64)  NOT NULL,
100	    fingerprint     VARCHAR(128) NOT NULL,
101	    response_status INT          NOT NULL,
102	    response_body   CLOB,
103	    created_at      BIGINT       NOT NULL,
104	    CONSTRAINT pk_idempotent_request PRIMARY KEY (request_id)
105	);
106	COMMENT ON TABLE  idempotent_request IS '写操作幂等记录表；仅记录成功请求，失败不占键，与业务变更同一事务原子提交';
107	COMMENT ON COLUMN idempotent_request.request_id IS '全局唯一 requestId（X-Request-Id）';
108	COMMENT ON COLUMN idempotent_request.actor_id IS '首次成功调用的操作者编号，属于幂等参数的一部分';
109	COMMENT ON COLUMN idempotent_request.role IS '首次成功调用的角色 COORDINATOR/REVIEWER，属于幂等参数的一部分';
110	COMMENT ON COLUMN idempotent_request.operation IS '写操作标识，如 experiment.create/allocation.create';
111	COMMENT ON COLUMN idempotent_request.fingerprint IS '请求参数指纹（含路径参数与请求体），与 actor/role 共同判定同参/异参';
112	COMMENT ON COLUMN idempotent_request.response_status IS '首次成功响应的 HTTP 状态码，重放时原样返回';
113	COMMENT ON COLUMN idempotent_request.response_body IS '首次成功响应体 JSON，重放时原样返回';
114	COMMENT ON COLUMN idempotent_request.created_at IS '记录时间，Unix 毫秒，UTC';
