1	package com.example.starter.blind.service;
2	
3	import com.example.starter.blind.ApiException;
4	import com.example.starter.blind.Clock;
5	import com.example.starter.blind.dto.UnblindRequestView;
6	import com.example.starter.blind.dto.UnblindResultView;
7	import com.example.starter.blind.repo.AllocationRepository.AllocationRow;
8	import com.example.starter.blind.repo.ExperimentRepository.SeatRow;
9	import com.example.starter.blind.repo.ExperimentRepository;
10	import com.example.starter.blind.repo.UnblindRequestRepository;
11	import com.example.starter.blind.repo.UnblindRequestRepository.UnblindRequestRow;
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	import java.util.UUID;
17	
18	/**
19	 * 揭盲申请/批准/结果业务：
20	 * 协调员为已分配参与者提出带原因申请，同一分配至多一个待审申请；
21	 * 须由另一名 REVIEWER 批准；仅申请人本人可查询结果，其他人 403，未批准 409。
22	 * 实验关闭、退组不撤销已批准的揭盲。
23	 */
24	@Service
25	public class UnblindService {
26	
27	    private final UnblindRequestRepository unblindRequestRepository;
28	    private final ExperimentService experimentService;
29	    private final ExperimentRepository experimentRepository;
30	    private final Clock clock;
31	
32	    public UnblindService(UnblindRequestRepository unblindRequestRepository,
33	                          ExperimentService experimentService,
34	                          ExperimentRepository experimentRepository,
35	                          Clock clock) {
36	        this.unblindRequestRepository = unblindRequestRepository;
37	        this.experimentService = experimentService;
38	        this.experimentRepository = experimentRepository;
39	        this.clock = clock;
40	    }
41	
42	    /**
43	     * 协调员提出揭盲申请。
44	     */
45	    @Transactional
46	    public UnblindRequestView apply(String experimentId, String participantId,
47	                                    String reason, String applicantActor) {
48	        if (reason == null || reason.isBlank()) {
49	            throw ApiException.badRequest("reason 不能为空");
50	        }
51	        if (reason.length() > 500) {
52	            throw ApiException.badRequest("reason 最长 500 字符");
53	        }
54	        AllocationRow allocation =
55	                experimentService.mustFindAllocationRow(experimentId, participantId);
56	        UnblindRequestRow pending =
57	                unblindRequestRepository.findPendingByAllocation(allocation.id());
58	        if (pending != null) {
59	            throw ApiException.conflict("该分配已存在待审揭盲申请");
60	        }
61	        String requestId = "UB-" + UUID.randomUUID().toString().replace("-", "");
62	        long now = clock.nowMillis();
63	        UnblindRequestRow row = new UnblindRequestRow(requestId, experimentId, participantId,
64	                allocation.id(), reason, applicantActor, null, "PENDING", null, now, null);
65	        try {
66	            unblindRequestRepository.insertPending(row);
67	        } catch (DuplicateKeyException e) {
68	            // 并发申请同一分配：唯一待审占位兜底。
69	            throw ApiException.conflict("该分配已存在待审揭盲申请");
70	        }
71	        return toView(row);
72	    }
73	
74	    /**
75	     * REVIEWER 批准申请；批准人不得是申请人本人。
76	     */
77	    @Transactional
78	    public UnblindRequestView approve(String unblindRequestId, String reviewerActor) {
79	        UnblindRequestRow row = unblindRequestRepository.lockById(unblindRequestId);
80	        if (row == null) {
81	            throw ApiException.notFound("揭盲申请不存在: " + unblindRequestId);
82	        }
83	        if ("APPROVED".equals(row.status())) {
84	            throw ApiException.conflict("揭盲申请已批准");
85	        }
86	        if (row.applicantActor().equals(reviewerActor)) {
87	            throw ApiException.forbidden("批准人必须是不同于申请人的另一名 REVIEWER");
88	        }
89	        // 从数据库读取处理映射（盲底），批准时写入申请记录；处理代码不打日志。
90	        AllocationRow allocation =
91	                experimentService.mustFindAllocationRow(row.experimentId(), row.participantId());
92	        SeatRow seat = experimentRepository.findSeat(row.experimentId(),
93	                allocation.blockNo(), allocation.seatNo());
94	        if (seat == null) {
95	            throw new IllegalStateException("席位映射缺失，数据不一致");
96	        }
97	        long now = clock.nowMillis();
98	        unblindRequestRepository.approve(unblindRequestId, reviewerActor,
99	                seat.treatment(), now);
100	        return new UnblindRequestView(row.id(), row.experimentId(), row.participantId(),
101	                row.reason(), row.applicantActor(), reviewerActor, "APPROVED",
102	                row.createdAt(), now);
103	    }
104	
105	    /**
106	     * 查询揭盲结果：仅申请人本人、且申请已批准时可获得处理代码。
107	     */
108	    public UnblindResultView getResult(String unblindRequestId, String actorId) {
109	        UnblindRequestRow row = unblindRequestRepository.findById(unblindRequestId);
110	        if (row == null) {
111	            throw ApiException.notFound("揭盲申请不存在: " + unblindRequestId);
112	        }
113	        if (!row.applicantActor().equals(actorId)) {
114	            // 其他人（含批准人）一律 403。
115	            throw ApiException.forbidden("仅揭盲申请人本人可查询揭盲结果");
116	        }
117	        if (!"APPROVED".equals(row.status())) {
118	            // 申请人本人查询但尚未批准：409。
119	            throw ApiException.conflict("揭盲申请尚未批准");
120	        }
121	        return new UnblindResultView(row.id(), row.experimentId(), row.participantId(),
122	                row.treatment(), row.status(), row.reviewedAt());
123	    }
